CREATE TABLE "areas_juridicas"("area_id" INTEGER PRIMARY KEY,"area_juridica" TEXT);
CREATE TABLE "clientes"("cliente_id" INTEGER PRIMARY KEY,"codigo_cliente" TEXT,"tipo_pessoa" TEXT,"uf" TEXT,"data_cadastro" TEXT,"status" TEXT);
CREATE TABLE "advogados"("advogado_id" INTEGER PRIMARY KEY,"codigo_advogado" TEXT,"area_id" INTEGER,"senioridade" TEXT,"valor_hora" REAL,FOREIGN KEY("area_id") REFERENCES "areas_juridicas"("area_id"));
CREATE TABLE "processos"("processo_id" INTEGER PRIMARY KEY,"codigo_processo" TEXT,"cliente_id" INTEGER,"area_id" INTEGER,"advogado_id" INTEGER,"data_abertura" TEXT,"data_encerramento" TEXT,"status" TEXT,"risco" TEXT,"valor_causa" REAL,"desfecho" TEXT,FOREIGN KEY("cliente_id") REFERENCES "clientes"("cliente_id"),FOREIGN KEY("area_id") REFERENCES "areas_juridicas"("area_id"),FOREIGN KEY("advogado_id") REFERENCES "advogados"("advogado_id"));
CREATE TABLE "prazos"("prazo_id" INTEGER PRIMARY KEY,"processo_id" INTEGER,"tipo_prazo" TEXT,"data_vencimento" TEXT,"data_conclusao" TEXT,"status" TEXT,"prioridade" TEXT,FOREIGN KEY("processo_id") REFERENCES "processos"("processo_id"));
CREATE TABLE "audiencias"("audiencia_id" INTEGER PRIMARY KEY,"processo_id" INTEGER,"data_audiencia" TEXT,"tipo" TEXT,"modalidade" TEXT,"status" TEXT,"resultado" TEXT,FOREIGN KEY("processo_id") REFERENCES "processos"("processo_id"));
CREATE TABLE "movimentacoes"("movimentacao_id" INTEGER PRIMARY KEY,"processo_id" INTEGER,"data_movimentacao" TEXT,"tipo" TEXT,"origem" TEXT,FOREIGN KEY("processo_id") REFERENCES "processos"("processo_id"));
CREATE TABLE "honorarios"("honorario_id" INTEGER PRIMARY KEY,"processo_id" INTEGER,"modelo_cobranca" TEXT,"valor_contratado" REAL,"percentual_exito" REAL,"data_contrato" TEXT,"status" TEXT,FOREIGN KEY("processo_id") REFERENCES "processos"("processo_id"));
CREATE TABLE "pagamentos"("pagamento_id" INTEGER PRIMARY KEY,"honorario_id" INTEGER,"parcela" INTEGER,"valor" REAL,"data_vencimento" TEXT,"data_pagamento" TEXT,"status" TEXT,FOREIGN KEY("honorario_id") REFERENCES "honorarios"("honorario_id"));